#!/usr/bin/env python3
"""Generate Sources/TiantingIM/ErrorCodes.gen.swift from protocol/errors.json.

Usage: python3 -I scripts/gen-errors/gen_errors.py [--check]
--check only compares and exits 1 when the generated file is stale (used by CI).
"""
import json
import pathlib
import re
import sys

ROOT = pathlib.Path(__file__).resolve().parents[2]
SPEC = ROOT / "protocol" / "errors.json"
OUT = ROOT / "Sources" / "TiantingIM" / "ErrorCodes.gen.swift"


SWIFT_KEYWORDS = {"internal", "public", "private", "default", "self", "class", "struct", "enum", "protocol"}


def camel(name: str) -> str:
    parts = name.lower().split("_")
    out = parts[0] + "".join(p.capitalize() for p in parts[1:])
    return f"`{out}`" if out in SWIFT_KEYWORDS else out


def swift_str(s: str) -> str:
    return '"' + s.replace("\\", "\\\\").replace('"', '\\"').replace("\n", "\\n") + '"'


def render(spec: dict) -> str:
    # Codes that belong only to console-server are not part of the end-user SDKs (PRD-admin 10.1).
    errors = [e for e in spec["errors"] if any(s != "console" for s in e["scope"])]
    lines = [
        "// Generated by scripts/gen-errors/gen_errors.py from protocol/errors.json. Do not edit.",
        "",
        "/// Error codes (protocol/errors.json).",
        "public enum ErrorCode {",
    ]
    lines += [f"    public static let {camel(e['name'])} = {e['code']}" for e in errors]
    lines += [
        "}",
        "",
        "struct ErrorInfo: Sendable {",
        "    let name: String",
        "    let retryable: Bool",
        "    let message: String",
        "}",
        "",
        "let errorInfoTable: [Int: ErrorInfo] = [",
    ]
    lines += [
        f"    {e['code']}: ErrorInfo(name: {swift_str(e['name'])}, "
        f"retryable: {'true' if e['retryable'] else 'false'}, message: {swift_str(e['message'])}),"
        for e in errors
    ]
    lines += ["]", "", "/// Codes the account and file HTTP endpoints return (`client` scope, PRD-chat 11.5, F-SYS-01).", "public let clientErrorCodes: [Int] = ["]
    lines += [f"    {e['code']}," for e in errors if "client" in e["scope"]]
    lines += ["]", "", "/// Error code -> the reasons that refine it (PRD-chat 11.5). A reason not listed here must not raise an error.", "public let errorReasons: [Int: [String]] = ["]
    reasons = {k: v for k, v in spec.get("reasons", {}).items() if k != "$comment"}
    lines += [f"    {k}: [{', '.join(swift_str(r) for r in v)}]," for k, v in reasons.items()]
    lines += ["]", "", "/// WebSocket close codes.", "public enum CloseCode {"]
    lines += [f"    public static let {camel(c['name'])} = {c['code']}" for c in spec["closeCodes"]]
    lines += [
        "}",
        "",
        "/// Whether to reconnect after a close code. Codes not listed here may reconnect.",
        "public let closeReconnect: [Int: Bool] = [",
    ]
    lines += [f"    {c['code']}: {'true' if c['reconnect'] else 'false'}," for c in spec["closeCodes"]]
    lines += [
        "]",
        "",
        "/// Kick reason -> close code (nil: reserved value, does not occur in phase one).",
        "public let kickCloseCode: [String: Int?] = [",
    ]
    for k in spec["kickReasons"]:
        code = "nil" if k["closeCode"] is None else str(k["closeCode"])
        lines.append(f"    {swift_str(k['reason'])}: {code},")
    lines += ["]", ""]
    return "\n".join(lines)


def main() -> int:
    text = render(json.loads(SPEC.read_text(encoding="utf-8")))
    if not re.search(r"public enum ErrorCode", text):
        raise SystemExit("render failed")
    if "--check" in sys.argv:
        if not OUT.exists() or OUT.read_text(encoding="utf-8") != text:
            print("ErrorCodes.gen.swift is out of date; run scripts/gen-errors/gen_errors.py", file=sys.stderr)
            return 1
        return 0
    OUT.write_text(text, encoding="utf-8")
    return 0


if __name__ == "__main__":
    sys.exit(main())
